const request = String($('Подготовка сообщения').first().json.text ?? '');
const lower = request.toLowerCase();
const elizovo = /елизов/.test(lower);
const petro = /петропавловск/.test(lower);
const visit = /(приед|приех|заед|зайд|посет|лично|вживую)/.test(lower) || (/(магазин|салон|шоурум)/.test(lower) && /(хоч|можно|собира|планир|посмотр|выбр|где|адрес|час|работ)/.test(lower));
const negated = /не\s+(?:хоч|собира|планир)\S*\s+(?:приех|приед|заех|зайд|посет)/.test(lower);
const hours = 'Пн–пт 10:00–18:00, сб 10:00–17:00, вс — выходной.';
return $input.all().map(item => {
  let answer = String(item.json.output?.[0]?.content?.[0]?.text ?? '').trim();
  answer = answer.replace(/\s*\((?:время\s+Камчатки|по\s+камчатскому\s+времени)\)|\s+по\s+(?:камчатскому\s+времени|времени\s+Камчатки)/gi, '');
  if (visit && !negated && elizovo !== petro) {
    const street = elizovo ? 'Западная' : 'Чубарова';
    const address = elizovo ? 'Елизово, ул. Западная, 4' : 'Петропавловск-Камчатский, ул. Чубарова, 16';
    if (!answer.toLowerCase().includes(street.toLowerCase())) answer += '\nАдрес магазина: ' + address + '.';
    if (!(/10[:.]00/.test(answer) && /18[:.]00/.test(answer) && /17[:.]00/.test(answer))) answer += '\nЧасы работы: ' + hours;
  }
  return { json: { ...item.json, final_text: answer.trim() } };
});

